components.css:
.btn--primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  height: 2.5rem;
  padding: 0 1rem;
  border: none;
  border-radius: 0.5rem;
  background: oklch(78.07% 0.136 5.02);
  color: oklch(100% 0 89.88);
  font-family: Geist, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  font-size: 0.875rem;
  font-weight: 500;
  line-height: 1.5;
  transition: background 200ms cubic-bezier(0.215, 0.61, 0.355, 1);
}
.btn--primary:hover { background: oklch(68.08% 0.148 5.02); }
.btn--primary:active { background: oklch(59.09% 0.1611 5.09); }
.btn--primary:focus-visible { outline: 2px solid oklch(0% 0 0 / 0.2); outline-offset: 2px; }
.btn--primary:disabled { opacity: 0.5; cursor: not-allowed; }

.btn--secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  height: 2.5rem;
  padding: 0 1rem;
  border: 1px solid oklch(0% 0 0 / 0.2);
  border-radius: 0.5rem;
  background: oklch(100% 0 89.88);
  color: oklch(20.46% 0 89.88);
  font-size: 0.875rem;
  font-weight: 500;
  transition: background 200ms cubic-bezier(0.215, 0.61, 0.355, 1);
}
.btn--secondary:hover { background: oklch(97.53% 0.0128 5.65); }
.btn--secondary:active { background: oklch(95.06% 0.0256 5.65); }
.btn--secondary:focus-visible { outline: 2px solid oklch(0% 0 0 / 0.2); outline-offset: 2px; }

.btn--ghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  border: none;
  border-radius: 0.5rem;
  background: transparent;
  color: oklch(68.3% 0 89.88);
  transition: background 200ms cubic-bezier(0.215, 0.61, 0.355, 1);
}
.btn--ghost:hover { background: oklch(0% 0 0 / 0.05); color: oklch(31.71% 0 89.88); }
.btn--ghost:focus-visible { outline: 2px solid oklch(0% 0 0 / 0.2); outline-offset: 2px; }

.field {
  width: 100%;
  height: 2.5rem;
  padding: 0 0.75rem;
  border: 1px solid oklch(0% 0 0 / 0.2);
  border-radius: 0.5rem;
  background: oklch(100% 0 89.88);
  color: oklch(20.46% 0 89.88);
  font-size: 0.875rem;
  line-height: 1.5;
  transition: border-color 200ms cubic-bezier(0.215, 0.61, 0.355, 1);
}
.field::placeholder { color: oklch(68.3% 0 89.88); }
.field:focus-visible { outline: 2px solid oklch(0% 0 0 / 0.2); outline-offset: 1px; border-color: oklch(0% 0 0); }
.field--error { border-color: oklch(44.46% 0.1774 26.79); }

.tag {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  height: 1.25rem;
  padding: 0 0.25rem;
  border: 1px solid oklch(0% 0 0 / 0.05);
  border-radius: 0.5rem;
  background: hsl(0, 0%, 96%);
  color: oklch(20.46% 0 89.88);
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.025em;
  transition: background 200ms cubic-bezier(0.215, 0.61, 0.355, 1);
}
.tag:hover { background: oklch(95.51% 0 89.88); }
.tag__dot { width: 0.5rem; height: 0.5rem; border-radius: 9999px; background: oklch(69.96% 0.202 44.44); }

.canvas-node {
  width: 6rem;
  min-height: 6rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem;
  border: 1.5px solid oklch(0% 0 0 / 0.1);
  border-radius: 1rem;
  background: oklch(100% 0 89.88);
  background-clip: padding-box;
  box-shadow: none;
  font-size: 0.8125rem;
  font-weight: 500;
  line-height: 1.5;
  transition: border-color 200ms cubic-bezier(0.215, 0.61, 0.355, 1);
}
.canvas-node--trigger { border-radius: 2.25rem 1rem 1rem 2.25rem; }
.canvas-node--selected { box-shadow: 0 0 0 calc(6px * var(--canvas-zoom-compensation-factor, 1)) hsla(220, 47%, 30%, 0.1); }
.canvas-node--success { border-width: 2px; border-color: oklch(52.96% 0.1495 148.99); }
.canvas-node--error { border-width: 2px; border-color: oklch(50.95% 0.2086 28.51); }
.canvas-node__icon { width: 2.5rem; height: 2.5rem; flex: none; }

.node-creator__row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  width: 100%;
  padding: 0.5rem 0.75rem;
  border: none;
  border-radius: 0.5rem;
  background: transparent;
  text-align: left;
  color: oklch(20.46% 0 89.88);
  transition: background 200ms cubic-bezier(0.215, 0.61, 0.355, 1);
}
.node-creator__row:hover { background: oklch(0% 0 0 / 0.05); }
.node-creator__row:focus-visible { outline: 2px solid oklch(0% 0 0 / 0.2); outline-offset: -2px; }
.node-creator__icon { width: 1.25rem; height: 1.25rem; flex: none; }
.node-creator__name { font-size: 0.875rem; font-weight: 500; line-height: 1.5; }
.node-creator__desc { font-size: 0.8125rem; line-height: 1.5; color: oklch(55.55% 0 89.88); }

.canvas-controls {
  display: flex;
  align-items: center;
  gap: 0.125rem;
  padding: 0.125rem;
  border: 1px solid oklch(0% 0 0 / 0.1);
  border-radius: 9999px;
  background: oklch(100% 0 89.88);
  box-shadow: 0 1px 2px -1px oklch(0% 0 0 / 0.1);
}
.canvas-controls button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  border: none;
  border-radius: 9999px;
  background: transparent;
  color: oklch(31.71% 0 89.88);
  transition: background 200ms cubic-bezier(0.215, 0.61, 0.355, 1);
}
.canvas-controls button:hover { background: oklch(0% 0 0 / 0.05); }
.canvas-controls button:focus-visible { outline: 2px solid oklch(0% 0 0 / 0.2); outline-offset: 2px; }

.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  height: 1.5rem;
  padding: 0 0.5rem;
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.025em;
}
.status-badge--success { background: oklch(98.19% 0.0181 155.83); border: 1px solid oklch(92.58% 0.0845 155.86); color: oklch(44.68% 0.1187 151.4); }
.status-badge--warning { background: oklch(97.27% 0.0706 103.29); border: 1px solid oklch(94.53% 0.1293 101.4); color: oklch(47.76% 0.1115 60.43); }
.status-badge--danger { background: oklch(97.05% 0.0129 17.38); border: 1px solid oklch(88.34% 0.0616 18.39); color: oklch(44.46% 0.1774 26.79); }
.status-badge--info { background: oklch(97.05% 0.0142 254.6); border: 1px solid oklch(88.2% 0.0588 253.97); color: oklch(42.42% 0.1982 265.5); }

.assistant-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.75rem 1rem;
  background: linear-gradient(105deg, #5b60e8 0%, #aa7bec 50%, #ec7b8e 100%);
  color: oklch(100% 0 89.88);
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: -0.007em;
}
